package main
import "fmt"

type Pessoa struct {
    nome string
    idade int
    sexo byte
}
func main() {
    var n int
    fmt.Scan(&n)

    pessoas := make([]Pessoa, n)
    for i := 0; i < n; i++ {
        var sexo string
        fmt.Scan(&pessoas[i].nome, &pessoas[i].idade, &sexo)
        pessoas[i].sexo = sexo[0]
    }

    IdMaior := -1
    nome := ""

    for _, v := range pessoas {
        if v.sexo == 'f' && v.idade > IdMaior {
            IdMaior = v.idade
            nome = v.nome
        }
    }
    if IdMaior == -1 {
        fmt.Println("nao tem mulher")
    } else {
    fmt.Println(nome)
    }
}
